import 'server-only';
import { readFile } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import { join } from 'node:path';
import { cookies } from 'next/headers';
import {
  JsonFileStore, isPublic,
  type DayRecord, type FestivalRecord, type HolidayRecord, type MoonPhaseRecord,
} from '@hindu-calendar/calendar-data';
import { DEFAULT_CITY, YEARS, isCity, todayNZ, addDaysISO, type CityId } from './cities';

export * from './cities';
export * from './format';

// Phase 1–2: JSON files in /data generated by the engine. A database-backed
// CalendarStore can replace JsonFileStore later without touching pages.
// The data folder sits at the repo root; the working directory differs between build,
// `next start` and Vercel functions, so look in the likely places.
const DATA_DIR = [join(process.cwd(), '..', '..', 'data'), join(process.cwd(), 'data'), join(process.cwd(), '..', 'data')]
  .find((d) => existsSync(join(d, '2027', 'holidays.json'))) ?? join(process.cwd(), '..', '..', 'data');
const cache = new Map<string, unknown>();
const store = new JsonFileStore(async (p) => {
  if (!cache.has(p)) cache.set(p, JSON.parse(await readFile(join(DATA_DIR, p), 'utf8')));
  return cache.get(p);
});

/**
 * DATA_MODE
 *  preview    – internal: shows CALCULATED data with an "internal preview" banner.
 *  calculated – public: shows CALCULATED data, each clearly labelled "calculated – not yet reviewed".
 *  public     – shows only APPROVED / PUBLISHED festival records.
 */
export type Mode = 'preview' | 'calculated' | 'public';
export const MODE: Mode = process.env.DATA_MODE === 'preview' ? 'preview' : process.env.DATA_MODE === 'calculated' ? 'calculated' : 'public';
export const showCalculated = MODE !== 'public';

export type Festival = FestivalRecord & { slug: string; category?: string };

export async function getDays(year: number, city: string): Promise<DayRecord[]> {
  return store.days(year, city);
}

export async function getFestivals(year: number, city: string): Promise<Festival[]> {
  const all = (await store.festivals(year, city)) as Festival[];
  // Stable, city-independent slugs: dated ids (Ekadashis, monthly vrats) use their name,
  // with -2, -3 for repeats within the year (e.g. two Saphala Ekadashis).
  const seen = new Map<string, number>();
  const slugify = (s: string) => s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
  return all
    .filter((f) => showCalculated || isPublic(f))
    .map((f) => {
      const base = f.slug ?? (/\d{4}-\d{2}-\d{2}$/.test(f.id) ? slugify(f.name) : f.id);
      const n = (seen.get(base) ?? 0) + 1;
      seen.set(base, n);
      return { ...f, slug: n === 1 ? base : `${base}-${n}` };
    });
}

export async function getFestival(year: number, city: string, slug: string) {
  return (await getFestivals(year, city)).find((f) => f.slug === slug) ?? null;
}

export async function getHolidays(year: number): Promise<HolidayRecord[]> {
  return store.holidays(year);
}

export async function getMoonPhases(year: number, city: string): Promise<MoonPhaseRecord[]> {
  return store.moonPhases(year, city);
}

/** Festivals from today for `days` days, across year boundaries. */
export async function upcomingFestivals(city: string, days: number, filter?: (f: Festival) => boolean) {
  const from = todayNZ();
  const to = addDaysISO(from, days);
  const years = YEARS.filter((y) => y >= Number(from.slice(0, 4)) && y <= Number(to.slice(0, 4)));
  const lists = await Promise.all(years.map((y) => getFestivals(y, city)));
  return lists.flat().filter((f) => f.date >= from && f.date <= to && (!filter || filter(f)));
}

/** City chosen by the visitor (cookie), else Auckland. */
export async function preferredCity(): Promise<CityId> {
  const c = (await cookies()).get('city')?.value;
  return isCity(c) ? c : DEFAULT_CITY;
}
